// Transcribed from solid-js@2.0.0-rc.3, the prerelease this repository audits.
// `solid-js`' own `types/index.d.ts` re-exports `untrack` from
// `@solidjs/signals` (line 1) and `createMemo` from `./client/hydration.js`
// (line 8). Both signatures a result here depends on are byte-faithful:
//
// - `untrack`    `@solidjs/signals@2.0.0-rc.3` `dist/types/core/core.d.ts:75`
// - `createMemo` `solid-js@2.0.0-rc.3` `types/client/hydration.d.ts:206-211`,
//                with `HydrationMemoOptions<T> = MemoOptions<T>` (`:66`)
//
// and so are the types they name: `NoInfer`, `ComputeFunction`, `Accessor`,
// `SourceAccessor`/`Refreshable` (`dist/types/signals.d.ts:49-50,68,225`,
// `dist/types/core/constants.d.ts:95-97`). `MemoOptions` keeps every member
// of `dist/types/signals.d.ts:158-237` with the documentation comments
// dropped; an option object cannot create a callback row.
declare const $REFRESH: unique symbol;
export type Refreshable<T> = T & {
    readonly [$REFRESH]: any;
};
export type Accessor<T> = () => T;
export type SourceAccessor<T> = Refreshable<Accessor<T>>;
export type ComputeFunction<Prev, Next extends Prev = Prev> = (v: Prev) => PromiseLike<Next> | AsyncIterable<Next> | Next;
export type NoInfer<T extends any> = [T][T extends any ? 0 : never];
export interface MemoOptions<T> {
    id?: string;
    name?: string;
    transparent?: boolean;
    equals?: false | ((prev: T, next: T) => boolean);
    unobserved?: () => void;
    lazy?: boolean;
    sync?: boolean;
    loadingValue?: T;
}
type HydrationMemoOptions<T> = MemoOptions<T>;

export declare function untrack<T>(fn: () => T, strictReadLabel?: string | false): T;
export declare const createMemo: {
    <T>(compute: ComputeFunction<NoInfer<T>, T>, options: HydrationMemoOptions<T> & {
        loadingValue: T;
    }): SourceAccessor<T>;
    <T>(compute: ComputeFunction<undefined | NoInfer<T>, T>, options?: HydrationMemoOptions<T>): SourceAccessor<T>;
};
